-- Generated by model/lib/sql/generate.mjs. Loads IMPORT Control Total from cells/IMPORT Control Total.csv in the folder of input cells. Two rows for one cell add up.
-- @csv cells/IMPORT Control Total.csv
INSERT INTO "IMPORT Control Total" SELECT coalesce(k0."Country", fpabench_error('cells name a member Country does not have: ' || c."Country")), coalesce(k1."Years", fpabench_error('cells name a member Years does not have: ' || c."Years")), coalesce(k2."Months", fpabench_error('cells name a member Months does not have: ' || c."Months")), sum(c.value::DOUBLE PRECISION)
FROM csv c LEFT JOIN "dim Country" k0 ON k0.name = c."Country" LEFT JOIN "dim Years" k1 ON k1.name = c."Years" LEFT JOIN "dim Months" k2 ON k2.name = c."Months"
GROUP BY 1, 2, 3
ON CONFLICT ("Country", "Years", "Months") DO UPDATE SET v = EXCLUDED.v;
ANALYZE "IMPORT Control Total";
